import {api,escape,requestId} from './workspace-shared.js';
export function createDashboardWidgets({getClasses,onChange}){
 let records=[],error='',loading=true,dialog,epoch=0;
 const date=value=>new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(value));
 const item=row=>`<article class="dashboard-record"><div><strong>${escape(row.title)}</strong><small>${escape(row.learnerName)} · ${escape(row.className||'Class')}</small>${row.notes?`<p>${escape(row.notes)}</p>`:''}<small>${row.reviewDate?'Review '+escape(date(row.reviewDate+'T12:00:00')):date(row.createdAt)}${row.kind==='intervention'&&row.status==='resolved'?' · Resolved':''}</small></div>${row.kind==='intervention'?`<button class="text-button" type="button" data-record-status="${escape(row.id)}" data-status="${row.status==='active'?'resolved':'active'}">${row.status==='active'?'Mark resolved':'Reopen'}</button>`:''}</article>`;
 function html(){return `<div class="dashboard-support-grid">${['intervention','award'].map(kind=>{const all=records.filter(r=>r.kind===kind),current=kind==='intervention'?all.filter(r=>r.status==='active'):all,rest=all.filter(r=>!current.slice(0,3).includes(r));return `<section class="today-panel dashboard-widget" aria-labelledby="dashboard-${kind}-title"><div class="today-panel-heading"><h2 id="dashboard-${kind}-title"><span class="dashboard-widget-icon" aria-hidden="true">${kind==='intervention'?'↗':'☆'}</span>${kind==='intervention'?'Interventions':'Awards'} <span class="dashboard-widget-count">${loading?'…':error?'':current.length}</span></h2><button type="button" class="text-button" data-new-record="${kind}">${kind==='intervention'?'+ Add intervention':'+ Record award'}</button></div><p>${kind==='intervention'?'Plan support and keep the next review in sight.':'Celebrate effort, progress and achievement.'}</p>${loading?'<p class="today-panel-empty">Loading records…</p>':error?`<p role="status">${escape(error)} <button type="button" class="text-button" data-retry-records>Try again</button></p>`:current.length?current.slice(0,3).map(item).join(''):`<p class="today-panel-empty">${kind==='intervention'?'No active interventions. Add a support plan when a learner needs one.':'No awards recorded yet. Recognise a learner’s next achievement here.'}</p>`}${rest.length?`<details class="dashboard-record-history"><summary>${kind==='intervention'?'Intervention history':'More awards'} (${rest.length})</summary>${rest.map(item).join('')}</details>`:''}<small class="dashboard-widget-private">Your private teacher records</small></section>`;}).join('')}</div>`;}
 async function refresh(){const token=++epoch;try{const data=await api('/api/dashboard/records');if(token!==epoch)return;records=Array.isArray(data.records)?data.records:[];error='';}catch(e){if(token!==epoch)return;error=e.message;}loading=false;onChange();}
 async function status(id,value,button){button.disabled=true;try{const data=await api('/api/dashboard/records',{action:'status',id,status:value});records=records.map(row=>row.id===id?data.record:row);onChange();document.querySelector('[data-new-record="intervention"]')?.focus();}catch(e){button.disabled=false;error=e.message;onChange();}}
 function open(kind,opener){
  dialog?.remove();dialog=document.createElement('dialog');dialog.className='dashboard-record-dialog';dialog.setAttribute('aria-labelledby','dashboard-record-heading');
  const classes=getClasses();dialog.innerHTML=`<form><h2 id="dashboard-record-heading">${kind==='intervention'?'Add intervention':'Record award'}</h2><p>Your private teacher record for this learner.</p><label>Class<select name="classId" required>${classes.length?classes.map(c=>`<option value="${escape(c.id)}">${escape(c.name)}</option>`).join(''):'<option value="">Create a class first</option>'}</select></label><label>Learner<select name="learnerId" required disabled><option value="">Loading learners…</option></select></label><label>${kind==='intervention'?'Support focus':'Award'}<input name="title" required maxlength="160" placeholder="${kind==='intervention'?'e.g. Using evidence in paragraphs':'e.g. Resilience in writing'}"></label><label>${kind==='intervention'?'Plan and next steps':'Reason for recognition'}<textarea name="notes" maxlength="1200" rows="3"></textarea></label>${kind==='intervention'?'<label>Review date <span>(optional)</span><input name="reviewDate" type="date"></label>':''}<p role="alert" data-record-error></p><div class="dialog-actions"><button type="button" class="teacher-button secondary" data-record-cancel>Cancel</button><button type="submit" class="teacher-button" ${classes.length?'':'disabled'}>Save ${kind==='intervention'?'intervention':'award'}</button></div></form>`;
  document.body.append(dialog);const form=dialog.querySelector('form'),classField=form.elements.classId,learner=form.elements.learnerId,message=dialog.querySelector('[data-record-error]'),save=form.querySelector('[type=submit]');let generation=0;const id=requestId();
  const close=()=>dialog.close();dialog.querySelector('[data-record-cancel]').onclick=close;dialog.addEventListener('close',()=>{dialog.remove();document.querySelector('[data-new-record="'+kind+'"]')?.focus();},{once:true});
  async function roster(){const token=++generation;learner.disabled=save.disabled=true;message.textContent='';if(!classField.value){learner.innerHTML='<option value="">Create a class first</option>';return;}try{const data=await api('/api/enrollment/classes/'+encodeURIComponent(classField.value)+'/roster');if(token!==generation)return;learner.innerHTML=data.students.length?data.students.map(s=>`<option value="${escape(s.id)}">${escape(s.name)}</option>`).join(''):'<option value="">Add learners to this class first</option>';learner.disabled=save.disabled=!data.students.length;}catch(e){if(token!==generation)return;learner.innerHTML='<option value="">Learners unavailable</option>';message.textContent=e.message;}}
  classField.onchange=roster;form.onsubmit=async event=>{event.preventDefault();save.disabled=true;message.textContent='';try{const data=await api('/api/dashboard/records',{id,action:'create',kind,classId:classField.value,learnerId:learner.value,title:form.elements.title.value,notes:form.elements.notes.value,reviewDate:form.elements.reviewDate?.value||''});records=[data.record,...records.filter(row=>row.id!==id)];error='';loading=false;close();onChange();}catch(e){message.textContent=e.message;save.disabled=false;}};
  dialog.showModal();roster();
 }
 return {html,refresh,open,status,clear(){epoch++;records=[];loading=true;error='';dialog?.close();}};
}
